Object.assign(window.CODELAB_OFFLINE_PACKS,{"topic-02may1822signoftheproductofanarray":{"key":"topic-02may1822signoftheproductofanarray","number":null,"title":"02 MAY 1822 Sign of the Product of an Array","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"02-MAY 1822 Sign of the Product of an Array.py","code":"class Solution:\n    def arraySign(self, nums: List[int]) -> int:\n        result = 1\n        for num in nums:\n            if num > 0:\n                result *= 1\n            elif num < 0:\n                result *= -1\n            else:\n                result *= 0\n            if result == 0:\n                return 0\n        return result","hash":"9ca38a304e74157ce4ba6417c5d3c365c01f638978453e2a770f3a22c14dc5ff","origins":[{"source":"solutions","path":"LeetCoding Challenges/2023/2023-05 Leetcoding Challenge/02-MAY 1822 Sign of the Product of an Array.py"}]}],"sources":["solutions"]},"topic-02nov2265countnodesequaltoaverageofsubtree":{"key":"topic-02nov2265countnodesequaltoaverageofsubtree","number":null,"title":"02 NOV 2265 Count Nodes Equal to Average of Subtree","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"02-NOV 2265 Count Nodes Equal to Average of Subtree.py","code":"# Definition for a binary tree node.\n# class TreeNode:\n#     def __init__(self, val=0, left=None, right=None):\n#         self.val = val\n#         self.left = left\n#         self.right = right\nclass Solution:\n    def averageOfSubtree(self, root: Optional[TreeNode]) -> int:\n        count = 0\n        def postOrder(node):\n            nonlocal count\n            if node == None:\n                return (0, 0)\n            leftSum, leftCount = postOrder(node.left)\n            rightSum, rightCount = postOrder(node.right)\n            nodeSum, nodeCount = leftSum + rightSum + node.val, leftCount + rightCount + 1\n            if (nodeSum // nodeCount) == node.val:\n                count += 1\n            return (nodeSum, nodeCount)\n        postOrder(root)\n        return count","hash":"1d9add622a1cb83635b4272349c40f878350e3f7b0f5d785de3527c5d9ac2814","origins":[{"source":"solutions","path":"November 2023 Leetcoding Challenge/02-NOV 2265 Count Nodes Equal to Average of Subtree.py"}]}],"sources":["solutions"]},"topic-02oct2038removecoloredpiecesifbothneighborsarethesamecolor":{"key":"topic-02oct2038removecoloredpiecesifbothneighborsarethesamecolor","number":null,"title":"02 OCT 2038 Remove Colored Pieces if Both Neighbors are the Same Color","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"02-OCT 2038 Remove Colored Pieces if Both Neighbors are the Same Color.py","code":"class Solution:\n    def winnerOfGame(self, colors: str) -> bool:\n        alice, bob = 0, 0\n        for i in range(1, len(colors) - 1):\n            if colors[i - 1] == colors[i] == colors[i + 1]:\n                if colors[i] == 'A':\n                    alice += 1\n                else:\n                    bob += 1\n        return alice - bob >= 1","hash":"b46a48cb18a4f0587e0d4a52debcabbd3006832451ed4ee34fa1b675c61f3d80","origins":[{"source":"solutions","path":"LeetCoding Challenges/2023/2023-10 Leetcoding Challenge/02-OCT 2038 Remove Colored Pieces if Both Neighbors are the Same Color.py"}]}],"sources":["solutions"]},"topic-02sep2707extracharactersinastring":{"key":"topic-02sep2707extracharactersinastring","number":null,"title":"02 SEP 2707 Extra Characters in a String","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"02-SEP 2707 Extra Characters in a String.py","code":"class Solution:\n    def minExtraChar(self, s: str, dictionary: List[str]) -> int:\n        dictionarySet = set(dictionary)\n        @lru_cache(None)\n        def dp(start):\n            if start == len(s):\n                return 0\n            # To count this character as a left over character \n            # move to index 'start + 1'\n            result = dp(start + 1) + 1\n            for end in range(start, len(s)):\n                word = s[start: end + 1]\n                if word in dictionarySet:\n                    result = min(result, dp(end + 1))\n            return result\n        return dp(0)","hash":"5c8ae55934782a7aacc7cc8df89d618e2a53d93c066ea74c38fba9dd4c0368aa","origins":[{"source":"solutions","path":"LeetCoding Challenges/2023/2023-09 Leetcoding Challenge/02-SEP 2707 Extra Characters in a String.py"}]}],"sources":["solutions"]},"topic-03aug17lettercombinationsofaphonenumber":{"key":"topic-03aug17lettercombinationsofaphonenumber","number":null,"title":"03 AUG 17 Letter Combinations of a Phone Number","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"03-AUG 17 Letter Combinations of a Phone Number.py","code":"class Solution:\n    def letterCombinations(self, digits: str) -> List[str]:\n        if len(digits) == 0:\n            return []\n        DIGIT_LETTER_MAP = {\n            '2': ['a', 'b', 'c'],\n            '3': ['d', 'e', 'f'],\n            '4': ['g', 'h', 'i'],\n            '5': ['j', 'k', 'l'],\n            '6': ['m', 'n', 'o'],\n            '7': ['p', 'q', 'r', 's'],\n            '8': ['t', 'u', 'v'],\n            '9': ['w', 'x', 'y', 'z']\n        }\n        result = list()\n        def backtrack(currentString = [], currentIndex = 0):\n            if currentIndex == len(digits):\n                result.append(''.join(currentString))\n                return\n            elif currentIndex > len(digits):\n                return\n            for char in DIGIT_LETTER_MAP[digits[currentIndex]]:\n                currentString.append(char)\n                backtrack(currentString, currentIndex + 1)\n                currentString.pop()\n        backtrack()\n        return result","hash":"7a96aedab16060c297099460130a43d2660df39c28dd39cddc3ea8f436ba3918","origins":[{"source":"solutions","path":"LeetCoding Challenges/2023/2023-08 Leetcoding Challenge/03-AUG 17 Letter Combinations of a Phone Number.py"}]}],"sources":["solutions"]},"topic-03jan2125numberoflaserbeamsinabank":{"key":"topic-03jan2125numberoflaserbeamsinabank","number":null,"title":"03 JAN 2125 Number of Laser Beams in a Bank","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"03-JAN 2125 Number of Laser Beams in a Bank.py","code":"class Solution:\n    def numberOfBeams(self, bank: List[str]) -> int:\n        result, prevLaserCount = 0, 0\n        for lasers in bank:\n            laserCount = lasers.count('1')\n            if laserCount > 0:\n                result += laserCount * prevLaserCount\n                prevLaserCount = laserCount\n        return result","hash":"5d5ef8ec4ccd2be1c153c7c6e664e657e1534428ac3feb564ca6ef472bda5cb2","origins":[{"source":"solutions","path":"January 2024 Leetcoding Challenge/03-JAN 2125 Number of Laser Beams in a Bank.py"}]}],"sources":["solutions"]},"topic-03jul859buddystrings":{"key":"topic-03jul859buddystrings","number":null,"title":"03 JUL 859 Buddy Strings","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"03-JUL 859 Buddy Strings.py","code":"class Solution:\n    def buddyStrings(self, A: str, B: str) -> bool:\n        if len(A) != len(B):\n            return False\n        if A == B:\n            seen = set()\n            for char in A:\n                if char in seen:\n                    return True\n                seen.add(char)\n            return False\n        else:\n            pairs = []\n            for a, b in zip(A, B):\n                if a != b:\n                    pairs.append((a, b))\n                if len(pairs) > 2:\n                    return False\n            return len(pairs) == 2 and pairs[0] == pairs[1][::-1]","hash":"0a1cf2fb746d4672c6c3d57c32e3aa4fbb657bf164c5b140591bdc36efa64af7","origins":[{"source":"solutions","path":"LeetCoding Challenges/2023/2023-07 Leetcoding Challenge/03-JUL 859 Buddy Strings.py"}]}],"sources":["solutions"]},"topic-03jun1376timeneededtoinformallemployees":{"key":"topic-03jun1376timeneededtoinformallemployees","number":null,"title":"03 JUN 1376 Time Needed to Inform All Employees","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"03-JUN 1376 Time Needed to Inform All Employees.py","code":"class Solution:\n    def numOfMinutes(self, n: int, headID: int, manager: List[int], informTime: List[int]) -> int:\n        graph = defaultdict(list)\n        for index, managerId in enumerate(manager):\n            graph[managerId].append(index)\n        result = 0\n        def dfs(node, currentTime):\n            nonlocal graph, result\n            if node not in graph:\n                result = max(result, currentTime)\n                return\n            for emp in graph[node]:\n                dfs(emp, currentTime + informTime[node])\n        dfs(headID, 0)\n        return result","hash":"b7c56314ca9ac80f645b73dcba0a74ed81fdac77fc256cff9f2da0a7b94e3c49","origins":[{"source":"solutions","path":"LeetCoding Challenges/2023/2023-06 Leetcoding Challenge/03-JUN 1376 Time Needed to Inform All Employees.py"}]}],"sources":["solutions"]},"topic-03may2215findthedifferenceoftwoarrays":{"key":"topic-03may2215findthedifferenceoftwoarrays","number":null,"title":"03 MAY 2215 Find the Difference of Two Arrays","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"03-MAY 2215 Find the Difference of Two Arrays.py","code":"class Solution:\n    def findDifference(self, nums1: List[int], nums2: List[int]) -> List[List[int]]:\n        return [set(nums1) - set(nums2), set(nums2) - set(nums1)]","hash":"18eca6d0c01d24862ed3a3f0210ac06b9fda16e8f6d62891724b445f7f5e23d9","origins":[{"source":"solutions","path":"LeetCoding Challenges/2023/2023-05 Leetcoding Challenge/03-MAY 2215 Find the Difference of Two Arrays.py"}]}],"sources":["solutions"]},"topic-03nov1441buildanarraywithstackoperations":{"key":"topic-03nov1441buildanarraywithstackoperations","number":null,"title":"03 NOV 1441 Build an Array With Stack Operations","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"03-NOV 1441 Build an Array With Stack Operations.py","code":"class Solution:\n    def buildArray(self, target: List[int], n: int) -> List[str]:\n        result, i = [], 0\n        for num in target:\n            while i < num - 1:\n                result.append(\"Push\")\n                result.append(\"Pop\")\n                i += 1\n            result.append(\"Push\")\n            i += 1\n        return result","hash":"dc110fbe68a30f1c73482706768c0125c6b6ec11bf7f29ae03adc4f679f94ab7","origins":[{"source":"solutions","path":"November 2023 Leetcoding Challenge/03-NOV 1441 Build an Array With Stack Operations.py"}]}],"sources":["solutions"]},"topic-03oct1512numberofgoodpairs":{"key":"topic-03oct1512numberofgoodpairs","number":null,"title":"03 OCT 1512 Number of Good Pairs","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"03-OCT 1512 Number of Good Pairs.py","code":"class Solution:\n    def numIdenticalPairs(self, nums: List[int]) -> int:\n        return sum(((freq * (freq - 1)) // 2) for _, freq in Counter(nums).items())","hash":"60999e23882961e60d22c1f4f3b8bcf3dade4337f17dc7ab35a2b2dce5919f43","origins":[{"source":"solutions","path":"LeetCoding Challenges/2023/2023-10 Leetcoding Challenge/03-OCT 1512 Number of Good Pairs.py"}]}],"sources":["solutions"]},"topic-03sep62uniquepaths":{"key":"topic-03sep62uniquepaths","number":null,"title":"03 SEP 62 Unique Paths","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"03-SEP 62 Unique Paths.py","code":"class Solution:\n    def uniquePaths(self, m: int, n: int) -> int:\n        paths = [[1] * n for _ in range(m)]\n        for row in range(1, m):\n            for col in range(1, n):\n                paths[row][col] = paths[row-1][col] + paths[row][col-1]\n        return paths[m-1][n-1]","hash":"032023b71cba908a60b1860f83dbf15a673e9269837658efb9d825bb3697d44e","origins":[{"source":"solutions","path":"LeetCoding Challenges/2023/2023-09 Leetcoding Challenge/03-SEP 62 Unique Paths.py"}]}],"sources":["solutions"]},"topic-04aug139wordbreak":{"key":"topic-04aug139wordbreak","number":null,"title":"04 AUG 139 Word Break","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"04-AUG 139 Word Break.py","code":"class Solution:\n    def wordBreak(self, s: str, wordDict: List[str]) -> bool:\n        queue, wordDict, visited, sLength = deque([0]), set(wordDict), set(), len(s)\n        while queue:\n            start = queue.popleft()\n            if start not in visited:\n                for end in range(start + 1, sLength + 1):\n                    if s[start: end] in wordDict:\n                        queue.append(end)\n                        if end == sLength:\n                            return True\n                visited.add(start)\n        return False","hash":"eae8f9a60856ef3dff8b58585d8c68c5059e1442c25e97f13e85bb0b3a276c55","origins":[{"source":"solutions","path":"LeetCoding Challenges/2023/2023-08 Leetcoding Challenge/04-AUG 139 Word Break.py"}]}],"sources":["solutions"]},"topic-04jan2870minimumnumberofoperationstomakearrayempty":{"key":"topic-04jan2870minimumnumberofoperationstomakearrayempty","number":null,"title":"04 JAN 2870 Minimum Number of Operations to Make Array Empty","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"04-JAN 2870 Minimum Number of Operations to Make Array Empty.py","code":"class Solution:\n    def minOperations(self, nums: List[int]) -> int:\n        freqMap = Counter(nums)\n        result = 0\n        for value in freqMap.values():\n            if value == 1:\n                return -1\n            result += ceil(value / 3)\n        return result","hash":"5d0235324104a0f5cc3156bd85b9406ae6a9317a68638b8d7bf06658ea2db718","origins":[{"source":"solutions","path":"January 2024 Leetcoding Challenge/04-JAN 2870 Minimum Number of Operations to Make Array Empty.py"}]}],"sources":["solutions"]},"topic-04jul137singlenumberii":{"key":"topic-04jul137singlenumberii","number":null,"title":"04 JUL 137 Single Number II","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"04-JUL 137 Single Number II.py","code":"class Solution:\n    def singleNumber(self, nums: List[int]) -> int:\n        result = 0\n        def checkBit(num, i):\n            return (num >> i) & 1 == 1          # return positive value as is\n        for i in range(32):\n            bitCount = 0\n            for num in nums:\n                if checkBit(num, i):\n                    bitCount += 1\n            if bitCount % 3 == 1:\n                result |= (1 << i)\n        return result - 2 * (result & (1<<31))","hash":"bcf0a7c87e1a507660a50b608a760a54e09eaeb3e67c42280dd8ddab6c37f592","origins":[{"source":"solutions","path":"LeetCoding Challenges/2023/2023-07 Leetcoding Challenge/04-JUL 137 Single Number II.py"}]}],"sources":["solutions"]},"topic-04jun547numberofprovinces":{"key":"topic-04jun547numberofprovinces","number":null,"title":"04 JUN 547 Number of Provinces","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"04-JUN 547 Number of Provinces.py","code":"class Solution:\n    def findCircleNum(self, M: List[List[int]]) -> int:\n        visited, count = [0] * len(M), 0\n        def dfs(i):\n            for j in range(len(M)):\n                if M[i][j] == 1 and visited[j] == 0:\n                    visited[j] = 1\n                    dfs(j)\n        for i in range(len(M)):\n            if visited[i] == 0:\n                dfs(i)\n                count += 1\n        return count","hash":"b7ddd25286d08149b864886651fa4c9c5a5fa0b9ec1370317b4ecb1e7c9e0f41","origins":[{"source":"solutions","path":"LeetCoding Challenges/2023/2023-06 Leetcoding Challenge/04-JUN 547 Number of Provinces.py"}]}],"sources":["solutions"]},"topic-04may649dota2senate":{"key":"topic-04may649dota2senate","number":null,"title":"04 MAY 649 Dota2 Senate","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"04-MAY 649 Dota2 Senate.py","code":"class Solution:\n    def predictPartyVictory(self, senate: str) -> str:\n        queue = deque([])\n        rBan, rCount, dBan, dCount = 0, 0, 0, 0\n        for index, senator in enumerate(senate):\n            if senator == 'R':\n                rCount += 1\n            else:\n                dCount += 1\n            queue.append(senator)\n        while rCount and dCount:\n            senator = queue.popleft()\n            if senator == 'R':\n                if rBan > 0:\n                    rBan -= 1\n                    rCount -= 1\n                else:\n                    dBan += 1\n                    queue.append(senator)\n            else:\n                if dBan > 0:\n                    dBan -= 1\n                    dCount -= 1\n                else:\n                    rBan += 1\n                    queue.append(senator)\n        return 'Radiant' if rCount > 0 else 'Dire'","hash":"91d99de03f44fa0bd2e7ff40a4d860213e973ab4c128a506dfedb3fd19c715b0","origins":[{"source":"solutions","path":"LeetCoding Challenges/2023/2023-05 Leetcoding Challenge/04-MAY 649 Dota2 Senate.py"}]}],"sources":["solutions"]},"topic-04nov1503lastmomentbeforeallantsfalloutofaplank":{"key":"topic-04nov1503lastmomentbeforeallantsfalloutofaplank","number":null,"title":"04 NOV 1503 Last Moment Before All Ants Fall Out of a Plank","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"04-NOV 1503 Last Moment Before All Ants Fall Out of a Plank.py","code":"class Solution:\n    def getLastMoment(self, n: int, left: List[int], right: List[int]) -> int:\n        result = 0\n        for num in left:\n            result = max(num, result)\n        for num in right:\n            result = max(n - num, result)\n        return result","hash":"6f327d645db1453a11195edc6d005ea8e104435da1f3a819912984f7a0ec540c","origins":[{"source":"solutions","path":"November 2023 Leetcoding Challenge/04-NOV 1503 Last Moment Before All Ants Fall Out of a Plank.py"}]}],"sources":["solutions"]},"topic-04oct706designhashmap":{"key":"topic-04oct706designhashmap","number":null,"title":"04 OCT 706 Design Hash Map","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"04-OCT 706 Design HashMap.py","code":"class MyHashMap:\n\n    def __init__(self):\n        \"\"\"\n        Initialize your data structure here.\n        \"\"\"\n        self.hashMap = dict()\n\n    def put(self, key: int, value: int) -> None:\n        \"\"\"\n        value will always be non-negative.\n        \"\"\"\n        self.hashMap[key] = value\n\n    def get(self, key: int) -> int:\n        \"\"\"\n        Returns the value to which the specified key is mapped, or -1 if this map contains no mapping for the key\n        \"\"\"\n        return self.hashMap.get(key, -1)\n\n    def remove(self, key: int) -> None:\n        \"\"\"\n        Removes the mapping of the specified value key if this map contains a mapping for the key\n        \"\"\"\n        if key in self.hashMap:\n            del self.hashMap[key]\n\n\n# Your MyHashMap object will be instantiated and called as such:\n# obj = MyHashMap()\n# obj.put(key,value)\n# param_2 = obj.get(key)\n# obj.remove(key)","hash":"7dd7d92b41641c48cc70732760a4f895da733d6cdd905edf50b4fbf742d3c3b6","origins":[{"source":"solutions","path":"LeetCoding Challenges/2023/2023-10 Leetcoding Challenge/04-OCT 706 Design HashMap.py"}]}],"sources":["solutions"]},"topic-04sep141linkedlistcycle":{"key":"topic-04sep141linkedlistcycle","number":null,"title":"04 SEP 141 Linked List Cycle","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"04-SEP 141 Linked List Cycle.py","code":"# Definition for singly-linked list.\n# class ListNode:\n#     def __init__(self, x):\n#         self.val = x\n#         self.next = None\n\nclass Solution:\n    def hasCycle(self, head: Optional[ListNode]) -> bool:\n        if head is None or head.next is None:\n            return False\n        slowPointer = head\n        fastPointer = head.next\n        while slowPointer != fastPointer:\n            if fastPointer is None or fastPointer.next is None:\n                return False\n            fastPointer = fastPointer.next.next\n            slowPointer = slowPointer.next\n        return True","hash":"20e43ce43cd73efd5b4d8566004e8414b9c208f3cdec0610efadea6b5ee0d58a","origins":[{"source":"solutions","path":"LeetCoding Challenges/2023/2023-09 Leetcoding Challenge/04-SEP 141 Linked List Cycle.py"}]}],"sources":["solutions"]},"topic-05aug95uniquebinarysearchtreesii":{"key":"topic-05aug95uniquebinarysearchtreesii","number":null,"title":"05 AUG 95 Unique Binary Search Trees II","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"05-AUG 95 Unique Binary Search Trees II.py","code":"# Definition for a binary tree node.\n# class TreeNode:\n#     def __init__(self, val=0, left=None, right=None):\n#         self.val = val\n#         self.left = left\n#         self.right = right\nclass Solution:\n    def generateTrees(self, n: int) -> List[TreeNode]:\n        def generateTreesHelper(start, end):\n            if start > end:\n                return [None,]\n            trees = []\n            for i in range(start, end + 1):\n                leftSubTree = generateTreesHelper(start, i - 1)\n                rightSubTree = generateTreesHelper(i + 1, end)\n                for l in leftSubTree:\n                    for r in rightSubTree:\n                        root = TreeNode(i)\n                        root.left = l\n                        root.right = r\n                        trees.append(root)\n            return trees\n        return generateTreesHelper(1, n) if n else []","hash":"6767a305a04a549330efbcfb2630f74d79b78a5e1527ca2a16b481de26badb65","origins":[{"source":"solutions","path":"LeetCoding Challenges/2023/2023-08 Leetcoding Challenge/05-AUG 95 Unique Binary Search Trees II.py"}]}],"sources":["solutions"]},"topic-05jan300longestincreasingsubsequence":{"key":"topic-05jan300longestincreasingsubsequence","number":null,"title":"05 JAN 300 Longest Increasing Subsequence","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"05-JAN 300 Longest Increasing Subsequence.py","code":"class Solution:\n    def lengthOfLIS(self, nums: List[int]) -> int:\n        dp = [0] * len(nums)\n        currentLength = 0\n        for num in nums:\n            i = bisect.bisect_left(dp, num, 0, currentLength)\n            dp[i] = num\n            if i == currentLength:\n                currentLength += 1\n        return currentLength","hash":"19db21776ff681af7879bae4e5cabf1dc70d6904015f448fec8143d3f0b7a975","origins":[{"source":"solutions","path":"January 2024 Leetcoding Challenge/05-JAN 300 Longest Increasing Subsequence.py"}]}],"sources":["solutions"]},"topic-05jul1493longestsubarrayof1safterdeletingoneelement":{"key":"topic-05jul1493longestsubarrayof1safterdeletingoneelement","number":null,"title":"05 JUL 1493 Longest Subarray of 1's After Deleting One Element","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"05-JUL 1493 Longest Subarray of 1's After Deleting One Element.py","code":"class Solution:\n    def longestSubarray(self, nums: List[int]) -> int:\n        zeroCount, longestWindow, start = 0, 0, 0\n        for i in range(len(nums)):\n            zeroCount += 1 if nums[i] == 0 else 0\n            # Shrink the window until the zero counts come under the limit.\n            while zeroCount > 1:\n                zeroCount -= 1 if nums[start] == 0 else 0\n                start += 1\n            longestWindow = max(longestWindow, i - start)\n        return longestWindow","hash":"ce90fd342c8d68816dcf368b4ea7d430a1a7f54e435ff9c3e7a77a6d938ee51c","origins":[{"source":"solutions","path":"LeetCoding Challenges/2023/2023-07 Leetcoding Challenge/05-JUL 1493 Longest Subarray of 1's After Deleting One Element.py"}]}],"sources":["solutions"]},"topic-05jun1232checkifitisastraightline":{"key":"topic-05jun1232checkifitisastraightline","number":null,"title":"05 JUN 1232 Check If It Is a Straight Line","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"05-JUN 1232 Check If It Is a Straight Line.py","code":"class Solution:\n    def checkStraightLine(self, coordinates: List[List[int]]) -> bool:\n        if len(coordinates) in [0, 1, 2]:\n            return True\n        def getSlope(x, y):\n            if y[1] - x[1] == 0:\n                return 0\n            elif y[0] - x[0] == 0:\n                return float('inf')\n            else:\n                return ((y[1] - x[1]) / (y[0] - x[0]))\n        slope = getSlope(coordinates[0], coordinates[1])\n        for i in range(2, len(coordinates)):\n            if slope != getSlope(coordinates[i - 1], coordinates[i]):\n                return False\n        return True","hash":"a630d953f55f1b597ef8dae84df8013f90c000756c3e89dd7d9c57faa80f4391","origins":[{"source":"solutions","path":"LeetCoding Challenges/2023/2023-06 Leetcoding Challenge/05-JUN 1232 Check If It Is a Straight Line.py"}]}],"sources":["solutions"]},"topic-05may1456maximumnumberofvowelsinasubstringofgivenlength":{"key":"topic-05may1456maximumnumberofvowelsinasubstringofgivenlength","number":null,"title":"05 MAY 1456 Maximum Number of Vowels in a Substring of Given Length","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"05-MAY 1456 Maximum Number of Vowels in a Substring of Given Length.py","code":"class Solution:\n    def maxVowels(self, s: str, k: int) -> int:\n        \n        def isVowel(c: str) -> bool:\n            return c in 'aeiou'\n        \n        currLength = 0\n        for i in range(k):\n            if isVowel(s[i]):\n                currLength += 1\n        result = currLength\n        for i in range(k, len(s)):\n            if isVowel(s[i - k]):\n                currLength -= 1\n            if isVowel(s[i]):\n                currLength += 1\n            result = max(result, currLength)\n        return result","hash":"b70240d0442c4e8f9df2e21347071c71e640f621c64f60f27cd9499af5213d38","origins":[{"source":"solutions","path":"LeetCoding Challenges/2023/2023-05 Leetcoding Challenge/05-MAY 1456 Maximum Number of Vowels in a Substring of Given Length.py"}]}],"sources":["solutions"]},"topic-05nov1535findthewinnerofanarraygame":{"key":"topic-05nov1535findthewinnerofanarraygame","number":null,"title":"05 NOV 1535 Find the Winner of an Array Game","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"05-NOV 1535 Find the Winner of an Array Game.py","code":"class Solution:\n    def getWinner(self, arr: List[int], k: int) -> int:\n        maxElement, current, winStreak = max(arr), arr[0], 0\n        for i in range(1, len(arr)):\n            opponent = arr[i]\n            if current > opponent:\n                winStreak += 1\n            else:\n                current = opponent\n                winStreak = 1\n            if winStreak == k or current == maxElement:\n                return current","hash":"f80c16d95f0cf646795fe1118865c84e66630f7c2cd22ef61c0b156c7f7c31be","origins":[{"source":"solutions","path":"November 2023 Leetcoding Challenge/05-NOV 1535 Find the Winner of an Array Game.py"}]}],"sources":["solutions"]},"topic-05oct229majorityelementii":{"key":"topic-05oct229majorityelementii","number":null,"title":"05 OCT 229 Majority Element II","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"05-OCT 229 Majority Element II.py","code":"class Solution:\n    def majorityElement(self, nums: List[int]) -> List[int]:\n        if not nums:\n            return []\n        candidate1, count1, candidate2, count2 = None, 0, None, 0\n        for num in nums:\n            if candidate1 == num:\n                count1 += 1\n            elif candidate2 == num:\n                count2 += 1\n            elif count1 == 0:\n                candidate1 = num\n                count1 += 1\n            elif count2 == 0:\n                candidate2 = num\n                count2 += 1\n            else:\n                count1 -= 1\n                count2 -= 1\n        result = []\n        for candidate in [candidate1, candidate2]:\n            if nums.count(candidate) > len(nums) // 3:\n                result.append(candidate)\n        return result","hash":"2bb32357d39c1ab6d6b88232edc334bc122f61a1478913a2a154f5ffd65571dc","origins":[{"source":"solutions","path":"LeetCoding Challenges/2023/2023-10 Leetcoding Challenge/05-OCT 229 Majority Element II.py"}]}],"sources":["solutions"]},"topic-05sep138copylistwithrandompointer":{"key":"topic-05sep138copylistwithrandompointer","number":null,"title":"05 SEP 138 Copy List with Random Pointer","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"05-SEP 138 Copy List with Random Pointer.py","code":"\"\"\"\n# Definition for a Node.\nclass Node:\n    def __init__(self, x: int, next: 'Node' = None, random: 'Node' = None):\n        self.val = int(x)\n        self.next = next\n        self.random = random\n\"\"\"\n\nclass Solution:\n    def copyRandomList(self, head: 'Optional[Node]') -> 'Optional[Node]':\n        if head is None:\n            return None\n        currentNode = head\n        while currentNode:\n            newNode = Node(currentNode.val, None, None)\n            newNode.next = currentNode.next\n            currentNode.next = newNode\n            currentNode = newNode.next\n        currentNode = head\n        while currentNode:\n            currentNode.next.random = currentNode.random.next if currentNode.random else None\n            currentNode = currentNode.next.next\n        oldList = head\n        newList = head.next\n        currentNode = head.next\n        while oldList:\n            oldList.next = oldList.next.next\n            newList.next = newList.next.next if newList.next else None\n            oldList = oldList.next\n            newList = newList.next\n        return currentNode","hash":"19eaa9f67847746e4397664763515cfd92f7e33af7d266f453f7af91bac345df","origins":[{"source":"solutions","path":"LeetCoding Challenges/2023/2023-09 Leetcoding Challenge/05-SEP 138 Copy List with Random Pointer.py"}]}],"sources":["solutions"]},"topic-06aug920numberofmusicplaylists":{"key":"topic-06aug920numberofmusicplaylists","number":null,"title":"06 AUG 920 Number of Music Playlists","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"06-AUG 920 Number of Music Playlists.py","code":"class Solution:\n    def numMusicPlaylists(self, n: int, goal: int, k: int) -> int:\n        MOD = 10**9 + 7\n        # Initialize the DP table\n        dp = [[0 for _ in range(n + 1)] for _ in range(goal + 1)]\n        dp[0][0] = 1\n        for i in range(1, goal + 1):\n            for j in range(1, min(i, n) + 1):\n                # The i-th song is a new song\n                dp[i][j] = dp[i - 1][j - 1] * (n - j + 1) % MOD\n                # The i-th song is a song we have played before\n                if j > k:\n                    dp[i][j] = (dp[i][j] + dp[i - 1][j] * (j - k)) % MOD\n        return dp[goal][n]","hash":"3d76936a90003b1ca887d6d73ec36f500cef0b4254026e36ef82bc6636b1345b","origins":[{"source":"solutions","path":"LeetCoding Challenges/2023/2023-08 Leetcoding Challenge/06-AUG 920 Number of Music Playlists.py"}]}],"sources":["solutions"]},"topic-06jan1235maximumprofitinjobscheduling":{"key":"topic-06jan1235maximumprofitinjobscheduling","number":null,"title":"06 JAN 1235 Maximum Profit in Job Scheduling","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"06-JAN 1235 Maximum Profit in Job Scheduling.py","code":"class Solution:\n    def jobScheduling(self, startTime: List[int], endTime: List[int], profit: List[int]) -> int:\n        jobs = sorted(list(zip(startTime, endTime, profit)))\n        sortedStartedTime, N = [data[0] for data in jobs], len(jobs)\n        dp = [0] * (N + 1)\n        for k in range(N - 1, -1, -1):\n            index = bisect.bisect_left(sortedStartedTime, jobs[k][1])\n            dp[k] = max(jobs[k][2] + dp[index], dp[k + 1])\n        return dp[0]","hash":"063581e84dbd257892dae5acac12cb11c2dc6993ef4c7c8826cc525d8c99c076","origins":[{"source":"solutions","path":"January 2024 Leetcoding Challenge/06-JAN 1235 Maximum Profit in Job Scheduling.py"}]}],"sources":["solutions"]},"topic-06jul209minimumsizesubarraysum":{"key":"topic-06jul209minimumsizesubarraysum","number":null,"title":"06 JUL 209 Minimum Size Subarray Sum","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"06-JUL 209 Minimum Size Subarray Sum.py","code":"class Solution:\n    def minSubArrayLen(self, target: int, nums: List[int]) -> int:\n        minLength, start, end, currentSum = 10000000, 0, 0, 0\n        while end < len(nums):\n            currentSum += nums[end]\n            end += 1\n            while currentSum >= target:\n                minLength = min(end - start, minLength)\n                currentSum -= nums[start]\n                start += 1\n        return minLength if minLength != 10000000 else 0","hash":"266b9d59f16112b42570c5fa3314055fa0eef16d37bc20a955a2b60c12153c5d","origins":[{"source":"solutions","path":"LeetCoding Challenges/2023/2023-07 Leetcoding Challenge/06-JUL 209 Minimum Size Subarray Sum.py"}]}],"sources":["solutions"]},"topic-06jun1502canmakearithmeticprogressionfromsequence":{"key":"topic-06jun1502canmakearithmeticprogressionfromsequence","number":null,"title":"06 JUN 1502 Can Make Arithmetic Progression From Sequence","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"06-JUN 1502 Can Make Arithmetic Progression From Sequence.py","code":"class Solution:\n    def canMakeArithmeticProgression(self, arr: List[int]) -> bool:\n        sortedArr = sorted(arr)\n        diff = sortedArr[1] - sortedArr[0]\n        for i in range(2, len(sortedArr)):\n            if (sortedArr[i] - sortedArr[i - 1]) != diff:\n                return False\n        return True","hash":"3b3fb28ec7eaf8545f5952c8717bd413138bbd83d63aded7d42abca77e026567","origins":[{"source":"solutions","path":"LeetCoding Challenges/2023/2023-06 Leetcoding Challenge/06-JUN 1502 Can Make Arithmetic Progression From Sequence.py"}]}],"sources":["solutions"]},"topic-06may1498numberofsubsequencesthatsatisfythegivensumcondition":{"key":"topic-06may1498numberofsubsequencesthatsatisfythegivensumcondition","number":null,"title":"06 MAY 1498 Number of Subsequences That Satisfy the Given Sum Condition","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"06-MAY 1498 Number of Subsequences That Satisfy the Given Sum Condition.py","code":"class Solution:\n    def numSubseq(self, nums: List[int], target: int) -> int:\n        n, MOD, result = len(nums), 10 ** 9 + 7, 0\n        nums.sort()\n        for left in range(n):\n            # Find the insertion position for `target - nums[left]`\n            # 'right' equals the insertion index minus 1.\n            right = bisect.bisect_right(nums, target - nums[left]) - 1\n            if right >= left:\n                result += pow(2, right - left, MOD)\n        return result % MOD","hash":"f3be2c9f2ea28e36801c01f635fef72d53d25793ee0fe74d79bea216ecdf67f3","origins":[{"source":"solutions","path":"LeetCoding Challenges/2023/2023-05 Leetcoding Challenge/06-MAY 1498 Number of Subsequences That Satisfy the Given Sum Condition.py"}]}],"sources":["solutions"]},"topic-06nov1845seatreservationmanager":{"key":"topic-06nov1845seatreservationmanager","number":null,"title":"06 NOV 1845 Seat Reservation Manager","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"06-NOV 1845 Seat Reservation Manager.py","code":"class SeatManager:\n\n    def __init__(self, n: int):\n        self.heap = [i for i in range(1, n + 1)]\n        heapq.heapify(self.heap)\n\n    def reserve(self) -> int:\n        return heapq.heappop(self.heap)\n\n    def unreserve(self, seatNumber: int) -> None:\n        heapq.heappush(self.heap, seatNumber)\n\n\n# Your SeatManager object will be instantiated and called as such:\n# obj = SeatManager(n)\n# param_1 = obj.reserve()\n# obj.unreserve(seatNumber)","hash":"dc7fc423c9bf2160aefeeec729cae6f733e8a77349b358350ccf878d7b471449","origins":[{"source":"solutions","path":"November 2023 Leetcoding Challenge/06-NOV 1845 Seat Reservation Manager.py"}]}],"sources":["solutions"]},"topic-06oct343integerbreak":{"key":"topic-06oct343integerbreak","number":null,"title":"06 OCT 343 Integer Break","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"06-OCT 343 Integer Break.py","code":"class Solution:\n    def integerBreak(self, n: int) -> int:\n        @lru_cache(None)\n        def dp(num):\n            if num <= 3:\n                return num\n            result = num\n            for i in range(2, num):\n                result = max(result, i * dp(num - i))\n            return result\n        if n <= 3:\n            return n - 1\n        return dp(n)","hash":"f49380f9202fb004624a0c206a0b4623370e78fce2e777d2aef2d980c4f66fbf","origins":[{"source":"solutions","path":"LeetCoding Challenges/2023/2023-10 Leetcoding Challenge/06-OCT 343 Integer Break.py"}]}],"sources":["solutions"]},"topic-06sep725splitlinkedlistinparts":{"key":"topic-06sep725splitlinkedlistinparts","number":null,"title":"06 SEP 725 Split Linked List in Parts","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"06-SEP 725 Split Linked List in Parts.py","code":"# Definition for singly-linked list.\n# class ListNode:\n#     def __init__(self, val=0, next=None):\n#         self.val = val\n#         self.next = next\nclass Solution:\n    def splitListToParts(self, head: Optional[ListNode], k: int) -> List[Optional[ListNode]]:\n        current, count = head, 0\n        while current != None:\n            count, current = count + 1, current.next\n        splitSize, extraNodes = divmod(count, k)\n        result, current = [], head\n        for i in range(k):\n            splitHead = current\n            for j in range(splitSize + (i < extraNodes) - 1):\n                if current:\n                    current = current.next\n                else:\n                    break\n            if current:\n                current.next, current = None, current.next\n            result.append(splitHead)\n        return result","hash":"e407f5d3ffe9ad94b5eb6b75a46ceda6d4817961120ef011ee7c58de61b31a52","origins":[{"source":"solutions","path":"LeetCoding Challenges/2023/2023-09 Leetcoding Challenge/06-SEP 725 Split Linked List in Parts.py"}]}],"sources":["solutions"]},"topic-07aug74searcha2dmatrix":{"key":"topic-07aug74searcha2dmatrix","number":null,"title":"07 AUG 74 Search a 2D Matrix","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"07-AUG 74 Search a 2D Matrix.py","code":"class Solution:\n    def searchMatrix(self, matrix: List[List[int]], target: int) -> bool:\n        rows = len(matrix)\n        if rows == 0:\n            return False\n        cols = len(matrix[0])\n        size = rows * cols\n        low, high = 0, size - 1\n        while low <= high:\n            mid = low + ((high - low) // 2)\n            row, col = mid // cols, mid % cols\n            if matrix[row][col] == target:\n                return True\n            elif matrix[row][col] < target:\n                low = mid + 1\n            else:\n                high = mid - 1\n        return False","hash":"3cd372d62786230cf369235dd9d41f19e73c5870b3ec01538aba267485621e58","origins":[{"source":"solutions","path":"LeetCoding Challenges/2023/2023-08 Leetcoding Challenge/07-AUG 74 Search a 2D Matrix.py"}]}],"sources":["solutions"]},"topic-07jul2024maximizetheconfusionofanexam":{"key":"topic-07jul2024maximizetheconfusionofanexam","number":null,"title":"07 JUL 2024 Maximize the Confusion of an Exam","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"07-JUL 2024 Maximize the Confusion of an Exam.py","code":"class Solution:\n    def maxConsecutiveAnswers(self, answerKey: str, k: int) -> int:\n        max_size = k\n        count = collections.Counter(answerKey[:k])\n        \n        left = 0\n        for right in range(k, len(answerKey)):\n            count[answerKey[right]] += 1\n            \n            while min(count['T'], count['F']) > k: \n                count[answerKey[left]] -= 1\n                left += 1\n            \n            max_size = max(max_size, right - left + 1)\n                    \n        return max_size","hash":"d88191cb00872de757c2db2e54b2780f4e2bc4548b2ba00465683da0c1e3e776","origins":[{"source":"solutions","path":"LeetCoding Challenges/2023/2023-07 Leetcoding Challenge/07-JUL 2024 Maximize the Confusion of an Exam.py"}]}],"sources":["solutions"]},"topic-07jun1318minimumflipstomakeaorbequaltoc":{"key":"topic-07jun1318minimumflipstomakeaorbequaltoc","number":null,"title":"07 JUN 1318 Minimum Flips to Make a OR b Equal to c","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"07-JUN 1318 Minimum Flips to Make a OR b Equal to c.py","code":"class Solution:\n    def minFlips(self, a: int, b: int, c: int) -> int:\n        result = 0\n        while a or b or c:\n            if c & 1:\n                result += 0 if ((a & 1) or (b & 1)) else 1\n            else:\n                result += (a & 1) + (b & 1)\n            a >>= 1\n            b >>= 1\n            c >>= 1\n        return result","hash":"6a77c275aec8770eea8712772a6fed616bef5c9180ef4aecee914aa5701a5dca","origins":[{"source":"solutions","path":"LeetCoding Challenges/2023/2023-06 Leetcoding Challenge/07-JUN 1318 Minimum Flips to Make a OR b Equal to c.py"}]}],"sources":["solutions"]},"topic-07may1964findthelongestvalidobstaclecourseateachposition":{"key":"topic-07may1964findthelongestvalidobstaclecourseateachposition","number":null,"title":"07 MAY 1964 Find the Longest Valid Obstacle Course at Each Position","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"07-MAY 1964 Find the Longest Valid Obstacle Course at Each Position.py","code":"class Solution:\n    def longestObstacleCourseAtEachPosition(self, obstacles: List[int]) -> List[int]:\n        n = len(obstacles)\n        result = [1] * n\n        # lis[i] records the lowest increasing sequence of length i + 1.\n        lis = []\n        for i, height in enumerate(obstacles):\n            # Find the rightmost insertion position idx.\n            idx = bisect.bisect_right(lis, height)\n            if idx == len(lis):\n                lis.append(height)\n            else:\n                lis[idx] = height\n            result[i] = idx + 1\n        return result","hash":"e7f5e35aee63a2e903acd769182e310d5526597cda506e8c0a9dcda0ac0a333d","origins":[{"source":"solutions","path":"LeetCoding Challenges/2023/2023-05 Leetcoding Challenge/07-MAY 1964 Find the Longest Valid Obstacle Course at Each Position.py"}]}],"sources":["solutions"]},"topic-07nov1921eliminatemaximumnumberofmonsters":{"key":"topic-07nov1921eliminatemaximumnumberofmonsters","number":null,"title":"07 NOV 1921 Eliminate Maximum Number of Monsters","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"07-NOV 1921 Eliminate Maximum Number of Monsters.py","code":"class Solution:\n    def eliminateMaximum(self, dist: List[int], speed: List[int]) -> int:\n        arrivals = [d/s for d, s in zip(dist, speed)]\n        arrivals.sort()\n        result = 0\n        for i, arr in enumerate(arrivals):\n            if arr <= i:\n                break\n            result += 1\n        return result","hash":"fd3e0e42b2083d82611f3a4183c1ef8691eabb312e754a35d9a9e3951b30e490","origins":[{"source":"solutions","path":"November 2023 Leetcoding Challenge/07-NOV 1921 Eliminate Maximum Number of Monsters.py"}]}],"sources":["solutions"]},"topic-07oct1420buildarraywhereyoucanfindthemaximumexactlykcomparisons":{"key":"topic-07oct1420buildarraywhereyoucanfindthemaximumexactlykcomparisons","number":null,"title":"07 OCT 1420 Build Array Where You Can Find The Maximum Exactly K Comparisons","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"07-OCT 1420 Build Array Where You Can Find The Maximum Exactly K Comparisons.py","code":"class Solution:\n    def numOfArrays(self, n: int, m: int, k: int) -> int:\n        @cache\n        def dp(i, max_so_far, remain):\n            if i == n:\n                if remain == 0:\n                    return 1\n                \n                return 0\n            \n            ans = (max_so_far * dp(i + 1, max_so_far, remain)) % MOD\n            for num in range(max_so_far + 1, m + 1):\n                ans = (ans + dp(i + 1, num, remain - 1)) % MOD\n                \n            return ans\n        \n        MOD = 10 ** 9 + 7\n        return dp(0, 0, k)","hash":"d73079e61c20d197d0a223e19c27a9aeb576fedc7b98b75805cf03ec552176db","origins":[{"source":"solutions","path":"LeetCoding Challenges/2023/2023-10 Leetcoding Challenge/07-OCT 1420 Build Array Where You Can Find The Maximum Exactly K Comparisons.py"}]}],"sources":["solutions"]},"topic-07sep92reverselinkedlistii":{"key":"topic-07sep92reverselinkedlistii","number":null,"title":"07 SEP 92 Reverse Linked List II","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"07-SEP 92 Reverse Linked List II.py","code":"# Definition for singly-linked list.\n# class ListNode:\n#     def __init__(self, val=0, next=None):\n#         self.val = val\n#         self.next = next\nclass Solution:\n    def reverseBetween(self, head: ListNode, left: int, right: int) -> ListNode:\n        if not head:\n            return None\n        current, prev = head, None\n        while left > 1:\n            prev = current\n            current = current.next\n            left, right = left - 1, right - 1\n        tail, con = current, prev\n        while right:\n            third = current.next\n            current.next = prev\n            prev = current\n            current = third\n            right -= 1\n        if con:\n            con.next = prev\n        else:\n            head = prev\n        tail.next = current\n        return head","hash":"1e508d94e658626430d554776b7873d8b5e720093be4169281c0b86cd73d2067","origins":[{"source":"solutions","path":"LeetCoding Challenges/2023/2023-09 Leetcoding Challenge/07-SEP 92 Reverse Linked List II.py"}]}],"sources":["solutions"]},"topic-08aug33searchinrotatedsortedarray":{"key":"topic-08aug33searchinrotatedsortedarray","number":null,"title":"08 AUG 33 Search in Rotated Sorted Array","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"08-AUG 33 Search in Rotated Sorted Array.py","code":"class Solution:\n    def search(self, nums: List[int], target: int) -> int:\n        start, end = 0, len(nums) - 1\n        while start <= end:\n            pivot = start + (end - start) // 2\n            if nums[pivot] == target:\n                return pivot\n            elif nums[pivot] >= nums[start]:\n                if target >= nums[start] and target < nums[pivot]:\n                    end = pivot - 1\n                else:\n                    start = pivot + 1\n            else:\n                if target > nums[pivot] and target <= nums[end]:\n                    start = pivot + 1\n                else:\n                    end = pivot - 1\n        return -1","hash":"d3f2c77478ae8d1dcd4aabc350b98e4dfadb2015440ca829d548a0181207b0d7","origins":[{"source":"solutions","path":"LeetCoding Challenges/2023/2023-08 Leetcoding Challenge/08-AUG 33 Search in Rotated Sorted Array.py"}]}],"sources":["solutions"]},"topic-08jul2551putmarblesinbags":{"key":"topic-08jul2551putmarblesinbags","number":null,"title":"08 JUL 2551 Put Marbles in Bags","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"08-JUL 2551 Put Marbles in Bags.py","code":"class Solution:\n    def putMarbles(self, weights: List[int], k: int) -> int:\n        # We collect and sort the value of all n - 1 pairs.\n        n = len(weights)\n        pair_weights = [0] * (n - 1)\n        for i in range(n - 1):\n            pair_weights[i] = weights[i] + weights[i + 1]\n        pair_weights.sort()\n        \n        # Get the difference between the largest k - 1 values and the \n        # smallest k - 1 values.\n        answer = 0\n        for i in range(k - 1):\n            answer += pair_weights[n - 2 - i] - pair_weights[i]\n            \n        return answer","hash":"2513596048b8c78a6320c06b915db0f5111165671bda0788b5068b02070f735b","origins":[{"source":"solutions","path":"LeetCoding Challenges/2023/2023-07 Leetcoding Challenge/08-JUL 2551 Put Marbles in Bags.py"}]}],"sources":["solutions"]},"topic-08jun1351countnegativenumbersinasortedmatrix":{"key":"topic-08jun1351countnegativenumbersinasortedmatrix","number":null,"title":"08 JUN 1351 Count Negative Numbers in a Sorted Matrix","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"08 JUN 1351 Count Negative Numbers in a Sorted Matrix.py","code":"class Solution:\n    def countNegatives(self, grid: List[List[int]]) -> int:\n        count, n = 0, len(grid[0])\n        currRowNegativeIndex = n - 1\n        # Iterate on all rows of the matrix one by one.\n        for row in grid:\n            # Decrease 'currRowNegativeIndex' so that it points to current row's last positive element.\n            while currRowNegativeIndex >= 0 and row[currRowNegativeIndex] < 0:\n                currRowNegativeIndex -= 1\n            # 'currRowNegativeIndex' points to the last positive element,\n            # which means 'n - (currRowNegativeIndex + 1)' is the number of all negative elements.\n            count += (n - (currRowNegativeIndex + 1))\n        return count","hash":"46462f342f06190bc5e9950a38ee03043d1ea09bc8db9028041bd1fb9eb99701","origins":[{"source":"solutions","path":"LeetCoding Challenges/2023/2023-06 Leetcoding Challenge/08 JUN 1351 Count Negative Numbers in a Sorted Matrix.py"}]}],"sources":["solutions"]},"topic-08may1572matrixdiagonalsum":{"key":"topic-08may1572matrixdiagonalsum","number":null,"title":"08 MAY 1572 Matrix Diagonal Sum","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"08-MAY 1572 Matrix Diagonal Sum.py","code":"class Solution:\n    def diagonalSum(self, mat: List[List[int]]) -> int:\n        currentSum, n = 0, len(mat)\n        for i in range(n):\n            currentSum += mat[i][i]\n            if i != n - i - 1:\n                currentSum += mat[i][n - i - 1]\n        return currentSum","hash":"dedafd317c2475765bf4efb7fcb50b76a6bded8afeefbc720b84f557231f5a02","origins":[{"source":"solutions","path":"LeetCoding Challenges/2023/2023-05 Leetcoding Challenge/08-MAY 1572 Matrix Diagonal Sum.py"}]}],"sources":["solutions"]},"topic-08nov2849determineifacellisreachableatagiventime":{"key":"topic-08nov2849determineifacellisreachableatagiventime","number":null,"title":"08 NOV 2849 Determine if a Cell Is Reachable at a Given Time","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"08-NOV 2849 Determine if a Cell Is Reachable at a Given Time.py","code":"class Solution:\n    def isReachableAtTime(self, sx: int, sy: int, fx: int, fy: int, t: int) -> bool:\n        width, height = abs(sx - fx), abs(sy - fy)\n        if width == 0 and height == 0 and t == 1:\n            return False\n        return t >= max(width, height)","hash":"67a8d91d7abca4deab0e465457ce84d8710ebf150a1557b92d7ea19ebd211b0d","origins":[{"source":"solutions","path":"November 2023 Leetcoding Challenge/08-NOV 2849 Determine if a Cell Is Reachable at a Given Time.py"}]}],"sources":["solutions"]},"topic-08oct1458maxdotproductoftwosubsequences":{"key":"topic-08oct1458maxdotproductoftwosubsequences","number":null,"title":"08 OCT 1458 Max Dot Product of Two Subsequences","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"08-OCT 1458 Max Dot Product of Two Subsequences.py","code":"class Solution:\n    def maxDotProduct(self, nums1: List[int], nums2: List[int]) -> int:\n        @lru_cache(None)\n        def dp(i, j):\n            if i == len(nums1) or j == len(nums2):\n                return 0\n            currentResult = nums1[i] * nums2[j] + dp(i + 1, j + 1)\n            return max(currentResult, dp(i + 1, j), dp(i, j + 1))\n        if max(nums1) < 0 and min(nums2) > 0:\n            return max(nums1) * min(nums2)\n        if min(nums1) > 0 and max(nums2) < 0:\n            return min(nums1) * max(nums2)\n        return dp(0, 0)","hash":"b42058ad2b112cf809ab0c77da33df6f10ff95b47c2f7885ec4b73c0405d81f5","origins":[{"source":"solutions","path":"LeetCoding Challenges/2023/2023-10 Leetcoding Challenge/08-OCT 1458 Max Dot Product of Two Subsequences.py"}]}],"sources":["solutions"]},"topic-08sep118pascalstriangle":{"key":"topic-08sep118pascalstriangle","number":null,"title":"08 SEP 118 Pascal's Triangle","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"08-SEP 118 Pascal's Triangle.py","code":"class Solution:\n    def generate(self, numRows: int) -> List[List[int]]:\n        triangle = []\n        for rowNumber in range(numRows):\n            row = [None] * (rowNumber + 1)\n            row[0], row[-1] = 1, 1\n            for i in range(1, rowNumber):\n                row[i] = triangle[rowNumber - 1][i - 1] + triangle[rowNumber - 1][i]\n            triangle.append(row)\n        return triangle","hash":"600ac76789b97eb4239ca18686d18330365ebe0b6bd7ce0307ffe62d38231edb","origins":[{"source":"solutions","path":"LeetCoding Challenges/2023/2023-09 Leetcoding Challenge/08-SEP 118 Pascal's Triangle.py"}]}],"sources":["solutions"]},"topic-09aug2616minimizethemaximumdifferenceofpairs":{"key":"topic-09aug2616minimizethemaximumdifferenceofpairs","number":null,"title":"09 AUG 2616 Minimize the Maximum Difference of Pairs","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"09-AUG 2616 Minimize the Maximum Difference of Pairs.py","code":"class Solution:\n    def minimizeMax(self, nums: List[int], p: int) -> int:\n        nums.sort()\n        n = len(nums)\n        \n        # Find the number of valid pairs by greedy approach\n        def countValidPairs(threshold):\n            index, count = 0, 0\n            while index < n - 1:\n                # If a valid pair is found, skip both numbers.\n                if nums[index + 1] - nums[index] <= threshold:\n                    count += 1\n                    index += 1\n                index += 1\n            return count\n        \n        left, right = 0, nums[-1] - nums[0]\n        while left < right:\n            mid = left + (right - left) // 2\n\n            # If there are enough pairs, look for a smaller threshold.\n            # Otherwise, look for a larger threshold.\n            if countValidPairs(mid) >= p:\n                right = mid\n            else:\n                left = mid + 1\n        return left","hash":"6f71a78391d49efbccab83c2a6045a60634d50c8385d2d7cf5ecbfced02b2d39","origins":[{"source":"solutions","path":"LeetCoding Challenges/2023/2023-08 Leetcoding Challenge/09-AUG 2616 Minimize the Maximum Difference of Pairs.py"}]}],"sources":["solutions"]},"topic-09jul2272substringwithlargestvariance":{"key":"topic-09jul2272substringwithlargestvariance","number":null,"title":"09 JUL 2272 Substring With Largest Variance","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"09-JUL 2272 Substring With Largest Variance.py","code":"class Solution:\n    def largestVariance(self, s: str) -> int:\n        counter = [0] * 26\n        for char in s:\n            counter[ord(char) - ord('a')] += 1\n        globalMax = 0\n        for i in range(26):\n            for j in range(26):\n                # major and minor cannot be the same, and both must appear in s.\n                if i == j or counter[i] == 0 or counter[j] == 0:\n                    continue\n                # find the maximum variance of major - minor\n                major = chr(ord('a') + i)\n                minor = chr(ord('a') + j)\n                majorCount, minorCount = 0, 0\n                # The remaining minor in the rest of s\n                restMinor = counter[j]\n                for char in s:\n                    if char == major:\n                        majorCount += 1\n                    if char == minor:\n                        minorCount += 1\n                        restMinor -= 1\n                    # Only update the variance if there is at least one minor\n                    if minorCount > 0:\n                        globalMax = max(globalMax, majorCount - minorCount)\n                    # We can discard the previous string if there is at least one remaining minor\n                    if majorCount < minorCount and restMinor > 0:\n                        majorCount, minorCount = 0, 0\n        return globalMax","hash":"1ea671b56bbabee004d5f6190e6c8aa44e9f0243ae2bfda5127ba872106766d1","origins":[{"source":"solutions","path":"LeetCoding Challenges/2023/2023-07 Leetcoding Challenge/09-JUL 2272 Substring With Largest Variance.py"}]}],"sources":["solutions"]},"topic-09jun744findsmallestlettergreaterthantarget":{"key":"topic-09jun744findsmallestlettergreaterthantarget","number":null,"title":"09 JUN 744 Find Smallest Letter Greater Than Target","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"09-JUN 744 Find Smallest Letter Greater Than Target.py","code":"class Solution:\n    def nextGreatestLetter(self, letters: List[str], target: str) -> str:\n        return letters[bisect.bisect(letters, target) % len(letters)]","hash":"042d279499dcca64c73e2a823a546f7cf8fe00fcc3b4caaa24ceeff2d2b2585e","origins":[{"source":"solutions","path":"LeetCoding Challenges/2023/2023-06 Leetcoding Challenge/09-JUN 744 Find Smallest Letter Greater Than Target.py"}]}],"sources":["solutions"]},"topic-09may54spiralmatrix":{"key":"topic-09may54spiralmatrix","number":null,"title":"09 MAY 54 Spiral Matrix","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"09-MAY 54 Spiral Matrix.py","code":"class Solution:\n    def spiralOrder(self, matrix: List[List[int]]) -> List[int]:\n        def spiralCoordinates(r1, c1, r2, c2):\n            for c in range(c1, c2 + 1):\n                yield r1, c\n            for r in range(r1 + 1, r2 + 1):\n                yield r, c2\n            if r1 < r2 and c1 < c2:\n                for c in range(c2 - 1, c1, -1):\n                    yield r2, c\n                for r in range(r2, r1, -1):\n                    yield r, c1\n        \n        if not matrix:\n            return []\n        result, r1, r2, c1, c2 = [], 0, len(matrix) - 1, 0, len(matrix[0]) - 1\n        while r1 <= r2 and c1 <= c2:\n            for r, c in spiralCoordinates(r1, c1, r2, c2):\n                result.append(matrix[r][c])\n            r1 += 1\n            r2 -= 1\n            c1 += 1\n            c2 -= 1\n        return result","hash":"6360bbfa59f7a57beb8230533c1f8af2af77a353e05d7f69faa6bd6d97c56b33","origins":[{"source":"solutions","path":"LeetCoding Challenges/2023/2023-05 Leetcoding Challenge/09-MAY 54 Spiral Matrix.py"}]}],"sources":["solutions"]},"topic-09nov1759countnumberofhomogenoussubstrings":{"key":"topic-09nov1759countnumberofhomogenoussubstrings","number":null,"title":"09 NOV 1759 Count Number of Homogenous Substrings","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"09-NOV 1759 Count Number of Homogenous Substrings.py","code":"class Solution:\n    def countHomogenous(self, s: str) -> int:\n        result, currentStreak, MOD = 0, 0, 10 ** 9 + 7\n        for i in range(len(s)):\n            if i == 0 or s[i] == s[i - 1]:\n                currentStreak += 1\n            else:\n                currentStreak = 1\n            result = (result + currentStreak) % MOD\n        return result","hash":"6c4484e3b5a559eaab84415e16696125a03a9853bbb69c23c16e570a16d4fb56","origins":[{"source":"solutions","path":"November 2023 Leetcoding Challenge/09-NOV 1759 Count Number of Homogenous Substrings.py"}]}],"sources":["solutions"]},"topic-09oct34findfirstandlastpositionofelementinsortedarray":{"key":"topic-09oct34findfirstandlastpositionofelementinsortedarray","number":null,"title":"09 OCT 34 Find First and Last Position of Element in Sorted Array","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"09-OCT 34 Find First and Last Position of Element in Sorted Array.py","code":"class Solution:\n    def searchRange(self, nums: List[int], target: int) -> List[int]:\n        def indexSearch(nums, target, left):\n            low = 0\n            high = len(nums)\n            while low < high:\n                mid = (low + high) >> 1\n                if nums[mid] > target or (left and target == nums[mid]):\n                    high = mid\n                else:\n                    low = mid + 1\n            return low\n        \n        leftIndex = indexSearch(nums, target, True)\n        if leftIndex == len(nums) or nums[leftIndex] != target:\n            return [-1, -1]\n        else:\n            return [leftIndex, indexSearch(nums, target, False) - 1]","hash":"5a2632df06b53e76d8275be90b8418bae74b877af23cdec85fec8aa7251f200f","origins":[{"source":"solutions","path":"LeetCoding Challenges/2023/2023-10 Leetcoding Challenge/09-OCT 34 Find First and Last Position of Element in Sorted Array.py"}]}],"sources":["solutions"]},"topic-09sep377combinationsumiv":{"key":"topic-09sep377combinationsumiv","number":null,"title":"09 SEP 377 Combination Sum IV","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"09-SEP 377 Combination Sum IV.py","code":"class Solution:\n    def combinationSum4(self, nums: List[int], target: int) -> int:\n        nums.sort()\n        dp = [0 for _ in range(target + 1)]\n        dp[0] = 1\n        for combSum in range(target + 1):\n            for num in nums:\n                if combSum - num >= 0:\n                    dp[combSum] += dp[combSum - num]\n                else:\n                    break\n        return dp[target]","hash":"12e1925bf15a7d6b9679078f6faa9e7a56f2345b71fcd5d57cdc128d2b77bf1c","origins":[{"source":"solutions","path":"LeetCoding Challenges/2023/2023-09 Leetcoding Challenge/09-SEP 377 Combination Sum IV.py"}]}],"sources":["solutions"]},"topic-10aug81searchinrotatedsortedarrayii":{"key":"topic-10aug81searchinrotatedsortedarrayii","number":null,"title":"10 AUG 81 Search in Rotated Sorted Array II","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"10-AUG 81 Search in Rotated Sorted Array II.py","code":"class Solution:\n    def search(self, nums: List[int], target: int) -> bool:\n        if len(nums) == 0:\n            return False\n        start, end = 0, len(nums) - 1\n        def isBinarySearchHelpful(start, element):\n            return nums[start] != element\n        def existsInFirst(start, element):\n            return nums[start] <= element\n        while start <= end:\n            mid = start + ((end - start) >> 1)\n            if nums[mid] == target:\n                return True\n            if not isBinarySearchHelpful(start, nums[mid]):\n                start += 1\n                continue\n            pivotArray, targetArray = existsInFirst(start, nums[mid]), existsInFirst(start, target)\n            if pivotArray ^ targetArray:\n                if pivotArray:\n                    start = mid + 1\n                else:\n                    end = mid - 1\n            else:\n                if nums[mid] < target:\n                    start = mid + 1\n                else:\n                    end = mid - 1\n        return False","hash":"298061e4cd29c6742681a147f331be4091da9cb6319100b56ffc9910cb30de0c","origins":[{"source":"solutions","path":"LeetCoding Challenges/2023/2023-08 Leetcoding Challenge/10-AUG 81 Search in Rotated Sorted Array II.py"}]}],"sources":["solutions"]},"topic-10jul111minimumdepthofbinarytree":{"key":"topic-10jul111minimumdepthofbinarytree","number":null,"title":"10 JUL 111 Minimum Depth of Binary Tree","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"10-JUL 111 Minimum Depth of Binary Tree.py","code":"# Definition for a binary tree node.\n# class TreeNode:\n#     def __init__(self, val=0, left=None, right=None):\n#         self.val = val\n#         self.left = left\n#         self.right = right\nclass Solution:\n    def minDepth(self, root: Optional[TreeNode]) -> int:\n        self.result = float('inf')\n        def calculateDepth(node, depth):\n            if node:\n                if node.left is None and node.right is None:\n                    self.result = min(self.result, depth + 1)\n                else:\n                    if node.left:\n                        calculateDepth(node.left, depth + 1)\n                    if node.right:\n                        calculateDepth(node.right, depth + 1)\n        calculateDepth(root, 0)\n        return 0 if self.result == float('inf') else self.result","hash":"557238d2814388fc80963a01158136be0ddd737a8a3561414f4cee0fea114dec","origins":[{"source":"solutions","path":"LeetCoding Challenges/2023/2023-07 Leetcoding Challenge/10-JUL 111 Minimum Depth of Binary Tree.py"}]}],"sources":["solutions"]},"topic-10jun1802maximumvalueatagivenindexinaboundedarray":{"key":"topic-10jun1802maximumvalueatagivenindexinaboundedarray","number":null,"title":"10 JUN 1802 Maximum Value at a Given Index in a Bounded Array","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"10-JUN 1802 Maximum Value at a Given Index in a Bounded Array.py","code":"class Solution:\n    def maxValue(self, n: int, index: int, maxSum: int) -> int:\n        def getSum(index: int, value: int, n: int) -> int:\n            count = 0\n            # On index's left:\n            # If value > index, there are index + 1 numbers in the arithmetic sequence:\n            # [value - index, ..., value - 1, value].\n            # Otherwise, there are value numbers in the arithmetic sequence:\n            # [1, 2, ..., value - 1, value], plus a sequence of length (index - value + 1) of 1s. \n            if value > index:\n                count += (value + value - index) * (index + 1) // 2\n            else:\n                count += (value + 1) * value // 2 + index - value + 1\n            # On index's right:\n            # If value >= n - index, there are n - index numbers in the arithmetic sequence:\n            # [value, value - 1, ..., value - n + 1 + index].\n            # Otherwise, there are value numbers in the arithmetic sequence:\n            # [value, value - 1, ..., 1], plus a sequence of length (n - index - value) of 1s. \n            if value >= n - index:\n                count += (value + value - n + 1 + index) * (n - index) // 2\n            else:\n                count += (value + 1) * value // 2 + n - index - value\n            return count - value\n        \n        left, right = 1, maxSum\n        while left < right:\n            mid = (left + right + 1) // 2\n            if getSum(index, mid, n) <= maxSum:\n                left = mid\n            else:\n                right = mid - 1\n        return left","hash":"aaeac8c9cd787aa00e4e8ecb721dd763e0d3424f74ab76ff5265d5bb8069f53b","origins":[{"source":"solutions","path":"LeetCoding Challenges/2023/2023-06 Leetcoding Challenge/10-JUN 1802 Maximum Value at a Given Index in a Bounded Array.py"}]}],"sources":["solutions"]},"topic-10may59spiralmatrixii":{"key":"topic-10may59spiralmatrixii","number":null,"title":"10 MAY 59 Spiral Matrix II","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"10-MAY 59 Spiral Matrix II.py","code":"class Solution:\n    def generateMatrix(self, n: int) -> List[List[int]]:\n        result, count = [[0] * n for _ in range(n)], 1\n        for layer in range((n + 1) // 2):\n            for col in range(layer, n - layer):\n                result[layer][col] = count\n                count += 1\n            for row in range(layer + 1, n - layer):\n                result[row][n - layer - 1] = count\n                count += 1\n            for col in range(n - layer - 2, layer - 1, -1):\n                result[n - layer - 1][col] = count\n                count += 1\n            for row in range(n - layer - 2, layer, -1):\n                result[row][layer] = count\n                count += 1\n        return result","hash":"c0225daaf3bd346ec0a6d8c207eee478a679dda9207f6e57aa1d8b01adbd27c8","origins":[{"source":"solutions","path":"LeetCoding Challenges/2023/2023-05 Leetcoding Challenge/10-MAY 59 Spiral Matrix II.py"}]}],"sources":["solutions"]},"topic-10nov1743restorethearrayfromadjacentpairs":{"key":"topic-10nov1743restorethearrayfromadjacentpairs","number":null,"title":"10 NOV 1743 Restore the Array From Adjacent Pairs","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"10-NOV 1743 Restore the Array From Adjacent Pairs.py","code":"class Solution:\n    def restoreArray(self, adjacentPairs: List[List[int]]) -> List[int]:\n        graph = defaultdict(list)\n        for node1, node2 in adjacentPairs:\n            graph[node1].append(node2)\n            graph[node2].append(node1)\n        start = None\n        for key, value in graph.items():\n            if len(value) == 1:\n                root = key\n                break\n        result = []\n        def dfs(node, prev):\n            result.append(node)\n            for neighbour in graph[node]:\n                if neighbour != prev:\n                    dfs(neighbour, node)\n        dfs(root, None)\n        return result","hash":"285623f3a8532924df5f54ce0090fea608ddeed9776ecd295bba9849cc0868ed","origins":[{"source":"solutions","path":"November 2023 Leetcoding Challenge/10-NOV 1743 Restore the Array From Adjacent Pairs.py"}]}],"sources":["solutions"]},"topic-10oct2009minimumnumberofoperationstomakearraycontinuous":{"key":"topic-10oct2009minimumnumberofoperationstomakearraycontinuous","number":null,"title":"10 OCT 2009 Minimum Number of Operations to Make Array Continuous","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"10-OCT 2009 Minimum Number of Operations to Make Array Continuous.py","code":"class Solution:\n    def minOperations(self, nums: List[int]) -> int:\n        n = len(nums)\n        result, j = n, 0\n        sortedNums = sorted(set(nums))\n        for i in range(len(sortedNums)):\n            while j < len(sortedNums) and sortedNums[j] < sortedNums[i] + n:\n                j += 1\n            count = j - i\n            result = min(result, n - count)\n        return result","hash":"4d7a6e9ad0dfdce3b634911ae379c3674923c870c447f588b5258abe9640e34f","origins":[{"source":"solutions","path":"LeetCoding Challenges/2023/2023-10 Leetcoding Challenge/10-OCT 2009 Minimum Number of Operations to Make Array Continuous.py"}]}],"sources":["solutions"]},"topic-10sep1359countallvalidpickupanddeliveryoptions":{"key":"topic-10sep1359countallvalidpickupanddeliveryoptions","number":null,"title":"10 SEP 1359 Count All Valid Pickup and Delivery Options","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"10-SEP 1359 Count All Valid Pickup and Delivery Options.py","code":"class Solution:\n    def countOrders(self, n: int) -> int:\n        @functools.cache\n        def totalWays(unpicked, undelivered):\n            if not unpicked and not undelivered:\n                #We have completed all orders\n                return 1\n            if (unpicked < 0 or undelivered < 0 or undelivered < unpicked):\n                # We can't pick or deliver more than N items\n                # Number of deliveries can't exceed number of pickups \n                # as we can only deliver after a pickup.\n                return 0\n            # Count all choices of picking up an order.\n            ans = unpicked * totalWays(unpicked - 1, undelivered)\n            ans %= MOD\n            # Count all choices of delivering a picked order.\n            ans += (undelivered - unpicked) * totalWays(unpicked, undelivered - 1)\n            ans %= MOD\n            return ans\n        MOD = 1_000_000_007\n        return totalWays(n, n)","hash":"ba4ad59964dc4010e9b00970fe36474eaf5eefd2e413ed04f5c2f38f20d603c0","origins":[{"source":"solutions","path":"LeetCoding Challenges/2023/2023-09 Leetcoding Challenge/10-SEP 1359 Count All Valid Pickup and Delivery Options.py"}]}],"sources":["solutions"]},"topic-11aug518coinchangeii":{"key":"topic-11aug518coinchangeii","number":null,"title":"11 AUG 518 Coin Change II","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"11-AUG 518 Coin Change II.py","code":"class Solution:\n    def change(self, amount: int, coins: List[int]) -> int:\n        @lru_cache(None)\n        def numberOfWays(coinIndex: int, remainingAmount: int) -> int:\n            if remainingAmount == 0:\n                return 1\n            if coinIndex == len(coins):\n                return 0\n            if coins[coinIndex] > remainingAmount:\n                return numberOfWays(coinIndex + 1, remainingAmount)\n            else:\n                return numberOfWays(coinIndex, remainingAmount - coins[coinIndex]) + numberOfWays(coinIndex + 1, remainingAmount)\n        return numberOfWays(0, amount)","hash":"ade2b04284024037522bb68e75412e0d3b64aad83a63547980acb076ea15c0a4","origins":[{"source":"solutions","path":"LeetCoding Challenges/2023/2023-08 Leetcoding Challenge/11-AUG 518 Coin Change II.py"}]}],"sources":["solutions"]},"topic-11jul863allnodesdistancekinbinarytree":{"key":"topic-11jul863allnodesdistancekinbinarytree","number":null,"title":"11 JUL 863 All Nodes Distance K in Binary Tree","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"11-JUL 863 All Nodes Distance K in Binary Tree.py","code":"# Definition for a binary tree node.\n# class TreeNode:\n#     def __init__(self, x):\n#         self.val = x\n#         self.left = None\n#         self.right = None\n\nclass Solution:\n    def distanceK(self, root: TreeNode, target: TreeNode, k: int) -> List[int]:\n        parentMap = defaultdict(TreeNode)\n        def dfs(node: Optional[TreeNode], parent = None):\n            if node:\n                parentMap[node] = parent\n                dfs(node.left, node)\n                dfs(node.right, node)\n        dfs(root)\n        queue = deque([(target, 0),])\n        seen = { target }\n        while queue:\n            if queue[0][1] == k:\n                return [node.val for node, d in queue]\n            node, d = queue.popleft()\n            for neighbour in (node.left, node.right, parentMap[node]):\n                if neighbour and neighbour not in seen:\n                    seen.add(neighbour)\n                    queue.append((neighbour, d + 1))\n        return []","hash":"8e6977c3432e7edca3579e5acc49fc24822b991fe215b8e1fa3197df20b5f702","origins":[{"source":"solutions","path":"LeetCoding Challenges/2023/2023-07 Leetcoding Challenge/11-JUL 863 All Nodes Distance K in Binary Tree.py"}]}],"sources":["solutions"]},"topic-11jun1146snapshotarray":{"key":"topic-11jun1146snapshotarray","number":null,"title":"11 JUN 1146 Snapshot Array","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"11-JUN 1146 Snapshot Array.py","code":"class SnapshotArray:\n\n    def __init__(self, length: int):\n        self.data = [[[0, 0]] for _ in range(length)]\n        self.snapId = 0\n\n    def set(self, index: int, val: int) -> None:\n        _, snapId = self.data[index][-1]\n        if snapId == self.snapId:\n            self.data[index][-1][0] = val\n        else:\n            self.data[index].append([val, self.snapId])\n\n    def snap(self) -> int:\n        self.snapId += 1\n        return self.snapId - 1\n\n    def get(self, index: int, snap_id: int) -> int:\n        indexData = self.data[index]\n        startIndex, endIndex = 0, len(indexData) - 1\n        while startIndex < endIndex:\n            mid = startIndex + (endIndex - startIndex) // 2\n            val, snapId = indexData[mid]\n            if snapId > snap_id:\n                endIndex = mid\n            else:\n                startIndex = mid + 1\n        if indexData[startIndex][1] <= snap_id:\n            return indexData[startIndex][0]\n        return indexData[startIndex - 1][0]\n\n\n# Your SnapshotArray object will be instantiated and called as such:\n# obj = SnapshotArray(length)\n# obj.set(index,val)\n# param_2 = obj.snap()\n# param_3 = obj.get(index,snap_id)","hash":"fd065ffb15844a00e57a8091d4866e190039d61c9a141107e35d4fcd3eef6362","origins":[{"source":"solutions","path":"LeetCoding Challenges/2023/2023-06 Leetcoding Challenge/11-JUN 1146 Snapshot Array.py"}]}],"sources":["solutions"]},"topic-11may1035uncrossedlines":{"key":"topic-11may1035uncrossedlines","number":null,"title":"11 MAY 1035 Uncrossed Lines","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"11-MAY 1035 Uncrossed Lines.py","code":"class Solution:\n    def maxUncrossedLines(self, nums1: List[int], nums2: List[int]) -> int:\n        len1, len2 = len(nums1), len(nums2)\n        \n        @lru_cache(None)\n        def helper(n1: int, n2: int):\n            if n1 <= 0 or n2 <= 0:\n                return 0\n            if nums1[n1 - 1] == nums2[n2 - 1]:\n                return 1 + helper(n1 - 1, n2 - 1)\n            else:\n                return max(helper(n1 - 1, n2), helper(n1, n2 - 1))\n        \n        return helper(len1, len2)","hash":"b4f8f5ae9da3c87caa396cd6e52633e9a11afd8325ab3359af6a72d6012254f4","origins":[{"source":"solutions","path":"LeetCoding Challenges/2023/2023-05 Leetcoding Challenge/11-MAY 1035 Uncrossed Lines.py"}]}],"sources":["solutions"]},"topic-11nov2642designgraphwithshortestpathcalculator":{"key":"topic-11nov2642designgraphwithshortestpathcalculator","number":null,"title":"11 NOV 2642 Design Graph With Shortest Path Calculator","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"11-NOV 2642 Design Graph With Shortest Path Calculator.py","code":"class Graph:\n\n    def __init__(self, n: int, edges: List[List[int]]):\n        self.graph = defaultdict(list)\n        self.n = n\n        for fromNode, toNode, cost in edges:\n            self.graph[fromNode].append((toNode, cost))\n\n    def addEdge(self, edge: List[int]) -> None:\n        self.graph[edge[0]].append((edge[1], edge[2]))\n\n    def shortestPath(self, node1: int, node2: int) -> int:\n        pq = [(0, node1)]\n        costForNode = [inf] * self.n\n        costForNode[node1] = 0\n        while pq:\n            currentCost, currentNode = heappop(pq)\n            if currentCost > costForNode[currentNode]:\n                continue\n            if currentNode == node2:\n                return currentCost\n            for neighbour, cost in self.graph[currentNode]:\n                newCost = currentCost + cost\n                if newCost < costForNode[neighbour]:\n                    costForNode[neighbour] = newCost\n                    heappush(pq, (newCost, neighbour))\n        return -1\n\n\n# Your Graph object will be instantiated and called as such:\n# obj = Graph(n, edges)\n# obj.addEdge(edge)\n# param_2 = obj.shortestPath(node1,node2)","hash":"457c647a914cf0c303748968cd97113e41119df26e1758297be0e11cf386ca9d","origins":[{"source":"solutions","path":"November 2023 Leetcoding Challenge/11-NOV 2642 Design Graph With Shortest Path Calculator.py"}]}],"sources":["solutions"]},"topic-11oct2251numberofflowersinfullbloom":{"key":"topic-11oct2251numberofflowersinfullbloom","number":null,"title":"11 OCT 2251 Number of Flowers in Full Bloom","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"11-OCT 2251 Number of Flowers in Full Bloom.py","code":"from sortedcontainers import SortedDict\n\nclass Solution:\n    def fullBloomFlowers(self, flowers: List[List[int]], people: List[int]) -> List[int]:\n        difference = SortedDict({0: 0})\n        for start, end in flowers:\n            difference[start] = difference.get(start, 0) + 1\n            difference[end + 1] = difference.get(end + 1, 0) - 1\n        positions, prefix, curr = [], [], 0\n        for key, val in difference.items():\n            positions.append(key)\n            curr += val\n            prefix.append(curr)\n        result = []\n        for person in people:\n            i = bisect_right(positions, person) - 1\n            result.append(prefix[i])\n        return result","hash":"cba6c429a6eba6cb276ac4b2255729f9f09b5d2b729b660e987edc46093f2d34","origins":[{"source":"solutions","path":"LeetCoding Challenges/2023/2023-10 Leetcoding Challenge/11-OCT 2251 Number of Flowers in Full Bloom.py"}]}],"sources":["solutions"]},"topic-11sep1282groupthepeoplegiventhegroupsizetheybelongto":{"key":"topic-11sep1282groupthepeoplegiventhegroupsizetheybelongto","number":null,"title":"11 SEP 1282 Group the People Given the Group Size They Belong To","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"11-SEP 1282 Group the People Given the Group Size They Belong To.py","code":"class Solution:\n    def groupThePeople(self, groupSizes: List[int]) -> List[List[int]]:\n        groupSizeMap = defaultdict(list)\n        for person, groupSize in enumerate(groupSizes):\n            groupSizeMap[groupSize].append(person)\n        result = []\n        for groupSize, persons in groupSizeMap.items():\n            while persons:\n                group, persons = persons[:groupSize], persons[groupSize:]\n                result.append(group)\n        return result","hash":"7f49f0ec05d34c7154e44ba7b783d438a103e9fd06db3c1f378b9127056fe001","origins":[{"source":"solutions","path":"LeetCoding Challenges/2023/2023-09 Leetcoding Challenge/11-SEP 1282 Group the People Given the Group Size They Belong To.py"}]}],"sources":["solutions"]},"topic-12aug63uniquepathsii":{"key":"topic-12aug63uniquepathsii","number":null,"title":"12 AUG 63 Unique Paths II","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"12-AUG 63 Unique Paths II.py","code":"class Solution:\n    def uniquePathsWithObstacles(self, obstacleGrid: List[List[int]]) -> int:\n        if obstacleGrid[0][0] == 1:\n            return 0\n        else:\n            obstacleGrid[0][0] = 1\n        numberOfRows = len(obstacleGrid)\n        numberOfColumns = len(obstacleGrid[0])\n        for col in range(1, numberOfColumns):\n            if obstacleGrid[0][col] == 1:\n                obstacleGrid[0][col] = 0\n            else:\n                obstacleGrid[0][col] = obstacleGrid[0][col - 1]\n        for row in range(1, numberOfRows):\n            if obstacleGrid[row][0] == 1:\n                obstacleGrid[row][0] = 0\n            else:\n                obstacleGrid[row][0] = obstacleGrid[row - 1][0]\n        for row in range(1, numberOfRows):\n            for col in range(1, numberOfColumns):\n                if obstacleGrid[row][col] == 1:\n                    obstacleGrid[row][col] = 0\n                else:\n                    obstacleGrid[row][col] = obstacleGrid[row - 1][col] + obstacleGrid[row][col - 1]\n        return obstacleGrid[numberOfRows - 1][numberOfColumns - 1]","hash":"7027def50d60bb1b736794cb46c007541781477a0ac9df06cd4086d48f9a0ca5","origins":[{"source":"solutions","path":"LeetCoding Challenges/2023/2023-08 Leetcoding Challenge/12-AUG 63 Unique Paths II.py"}]}],"sources":["solutions"]},"topic-12jul802findeventualsafestates":{"key":"topic-12jul802findeventualsafestates","number":null,"title":"12 JUL 802 Find Eventual Safe States","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"12-JUL 802 Find Eventual Safe States.py","code":"class Solution:\n    def eventualSafeNodes(self, graph: List[List[int]]) -> List[int]:\n        n = len(graph)\n        indegree = [0] * n\n        adjList = defaultdict(list)\n        for i in range(n):\n            for node in graph[i]:\n                adjList[node].append(i)\n                indegree[i] += 1\n        queue = deque()\n        # Push all the nodes with indegree zero in the queue.\n        for i in range(n):\n            if indegree[i] == 0:\n                queue.append(i)\n        safe = [False] * n\n        while queue:\n            node = queue.popleft()\n            safe[node] = True\n            for neighbour in adjList[node]:\n                # Delete the edge \"node -> neighbour\".\n                indegree[neighbour] -= 1\n                if indegree[neighbour] == 0:\n                    queue.append(neighbour)\n        safeNodes = []\n        for i in range(n):\n            if safe[i]:\n                safeNodes.append(i)\n        return safeNodes","hash":"1f445c74997420e21da64d6cf5319cb969ccb2a186fc65391f738778626b36c1","origins":[{"source":"solutions","path":"LeetCoding Challenges/2023/2023-07 Leetcoding Challenge/12-JUL 802 Find Eventual Safe States.py"}]}],"sources":["solutions"]},"topic-12jun228summaryranges":{"key":"topic-12jun228summaryranges","number":null,"title":"12 JUN 228 Summary Ranges","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"12-JUN 228 Summary Ranges.py","code":"class Solution:\n    def summaryRanges(self, nums: List[int]) -> List[str]:\n        result, currentRange = [], []\n        for num in nums:\n            if len(currentRange) == 0:\n                currentRange = [num, num]\n            elif len(currentRange) == 2:\n                if currentRange[-1] + 1 == num:\n                    currentRange[-1] = num\n                else:\n                    result.append(currentRange)\n                    currentRange = [num, num]\n        if len(currentRange) == 2:\n            result.append(currentRange)\n        return [str(x[0]) + '->' + str(x[1]) if x[0] != x[1] else str(x[0]) for x in result]","hash":"16f54c811498e831fb8f38ccadccd711948b31993cdb9ce9699d3c41e983dac7","origins":[{"source":"solutions","path":"LeetCoding Challenges/2023/2023-06 Leetcoding Challenge/12-JUN 228 Summary Ranges.py"}]}],"sources":["solutions"]},"topic-12may2140solvingquestionswithbrainpower":{"key":"topic-12may2140solvingquestionswithbrainpower","number":null,"title":"12 MAY 2140 Solving Questions With Brainpower","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"12-MAY 2140 Solving Questions With Brainpower.py","code":"class Solution:\n    def mostPoints(self, questions: List[List[int]]) -> int:\n        N = len(questions)\n\n        @lru_cache(None)\n        def helper(i: int) -> int:\n            if i > N - 1:\n                return 0\n            elif i == N - 1:\n                return questions[i][0]\n            else:\n                return max(helper(i + 1), questions[i][0] + helper(i + questions[i][1] + 1))\n        \n        return helper(0)","hash":"c7053c196d10f0a65ac57773c0f7cddeebf5c6c9ceea8c31a9113d70e81d6c31","origins":[{"source":"solutions","path":"LeetCoding Challenges/2023/2023-05 Leetcoding Challenge/12-MAY 2140 Solving Questions With Brainpower.py"}]}],"sources":["solutions"]},"topic-12nov815busroutes":{"key":"topic-12nov815busroutes","number":null,"title":"12 NOV 815 Bus Routes","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"12-NOV 815 Bus Routes.py","code":"class Solution:\n    def numBusesToDestination(self, routes: List[List[int]], source: int, target: int) -> int:\n        if source == target:\n            return 0\n        graph = defaultdict(list)\n        # Create a map from the bus stop to all the routes that include this stop.\n        for r in range(len(routes)):\n            for stop in routes[r]:\n                # Add all the routes that have this stop.\n                route = graph[stop]\n                route.append(r)\n                graph[stop] = route\n        queue = deque()\n        visited = set()\n        # Insert all the routes in the queue that have the source stop.\n        for route in graph[source]:\n            queue.append(route)\n            visited.add(route)\n        busCount = 1\n        while len(queue) != 0:\n            size = len(queue)\n            for i in range(size):\n                route = queue.popleft()\n                # Iterate over the stops in the current route.\n                for stop in routes[route]:\n                    # Return the current count if the target is found.\n                    if stop == target:\n                        return busCount\n                    # Iterate over the next possible routes from the current stop.\n                    for nextRoute in graph[stop]:\n                        if nextRoute not in visited:\n                            visited.add(nextRoute)\n                            queue.append(nextRoute)\n            busCount += 1\n        return -1","hash":"b306d18525c36972ce160932ed6210f1196ac52724b0e7eb8056f13911ca66a5","origins":[{"source":"solutions","path":"November 2023 Leetcoding Challenge/12-NOV 815 Bus Routes.py"}]}],"sources":["solutions"]},"topic-12oct1095findinmountainarray":{"key":"topic-12oct1095findinmountainarray","number":null,"title":"12 OCT 1095 Find in Mountain Array","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"12-OCT 1095 Find in Mountain Array.py","code":"# \"\"\"\n# This is MountainArray's API interface.\n# You should not implement it, or speculate about its implementation\n# \"\"\"\n#class MountainArray:\n#    def get(self, index: int) -> int:\n#    def length(self) -> int:\n\nclass Solution:\n    def findInMountainArray(self, target: int, mountain_arr: 'MountainArray') -> int:\n        # Save the length of the mountain array\n        length = mountain_arr.length()\n\n        # 1. Find the index of the peak element\n        low = 1\n        high = length - 2\n        while low != high:\n            test_index = (low + high) // 2\n            if mountain_arr.get(test_index) < mountain_arr.get(test_index + 1):\n                low = test_index + 1\n            else:\n                high = test_index\n        peak_index = low\n\n        # 2. Search in the strictly increasing part of the array\n        low = 0\n        high = peak_index\n        while low != high:\n            test_index = (low + high) // 2\n            if mountain_arr.get(test_index) < target:\n                low = test_index + 1\n            else:\n                high = test_index    \n        # Check if the target is present in the strictly increasing part\n        if mountain_arr.get(low) == target:\n            return low\n        \n        # 3. Otherwise, search in the strictly decreasing part\n        low = peak_index + 1\n        high = length - 1\n        while low != high:\n            test_index = (low + high) // 2\n            if mountain_arr.get(test_index) > target:\n                low = test_index + 1\n            else:\n                high = test_index\n        # Check if the target is present in the strictly decreasing part\n        if mountain_arr.get(low) == target:\n            return low\n        \n        # Target is not present in the mountain array\n        return -1","hash":"3c09216c541a09decf2e7e4fb7fbe32d7d679b3ab3682085fe0a0fb5baabe200","origins":[{"source":"solutions","path":"LeetCoding Challenges/2023/2023-10 Leetcoding Challenge/12-OCT 1095 Find in Mountain Array.py"}]}],"sources":["solutions"]},"topic-12sep1647minimumdeletionstomakecharacterfrequenciesunique":{"key":"topic-12sep1647minimumdeletionstomakecharacterfrequenciesunique","number":null,"title":"12 SEP 1647 Minimum Deletions to Make Character Frequencies Unique","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"12-SEP 1647 Minimum Deletions to Make Character Frequencies Unique.py","code":"class Solution:\n    def minDeletions(self, s: str) -> int:\n        freqMap = Counter(s)\n        frequency = sorted(freqMap.values(), reverse=True)\n        deleteCount, maxFreqAllowed = 0, len(s)\n        # Iterate over the frequencies in descending order\n        for freq in frequency:\n            # Delete characters to make the frequency equal the maximum frequency allowed\n            if freq > maxFreqAllowed:\n                deleteCount += freq - maxFreqAllowed\n                freq = maxFreqAllowed\n            # Update the maximum allowed frequency\n            maxFreqAllowed = max(0, freq - 1)\n        return deleteCount","hash":"a0bdf98b6a2ab65a65e83c88db4c06b7b84d5d3bf2d4641d43027cd2d07b4e62","origins":[{"source":"solutions","path":"LeetCoding Challenges/2023/2023-09 Leetcoding Challenge/12-SEP 1647 Minimum Deletions to Make Character Frequencies Unique.py"}]}],"sources":["solutions"]},"topic-13aug2369checkifthereisavalidpartitionforthearray":{"key":"topic-13aug2369checkifthereisavalidpartitionforthearray","number":null,"title":"13 AUG 2369 Check if There is a Valid Partition For The Array","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"13-AUG 2369 Check if There is a Valid Partition For The Array.py","code":"class Solution:\n    def validPartition(self, nums: List[int]) -> bool:\n        @lru_cache(None)\n        def isValidPrefix(i: int) -> bool:\n            if i == -1:\n                return True\n            result = False\n            if i > 0 and nums[i] == nums[i - 1]:\n                result |= isValidPrefix(i - 2)\n            if i > 1 and nums[i] == nums[i - 1] == nums[i - 2]:\n                result |= isValidPrefix(i - 3)\n            if i > 1 and nums[i] == nums[i - 1] + 1 == nums[i - 2] + 2:\n                result |= isValidPrefix(i - 3)\n            return result\n        return isValidPrefix(len(nums) - 1)","hash":"ca540dec09646236c425ca6016aa885580e692bd37cdf812aafbe3c7e0c520d9","origins":[{"source":"solutions","path":"LeetCoding Challenges/2023/2023-08 Leetcoding Challenge/13-AUG 2369 Check if There is a Valid Partition For The Array.py"}]}],"sources":["solutions"]},"topic-13jul207courseschedule":{"key":"topic-13jul207courseschedule","number":null,"title":"13 JUL 207 Course Schedule","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"13-JUL 207 Course Schedule.py","code":"class Solution:\n    def canFinish(self, numCourses: int, prerequisites: List[List[int]]) -> bool:\n        adjacencyList = defaultdict(list)\n        nodeInDegree = defaultdict(int)\n        totalEdges = 0\n        for destination, source in prerequisites:\n            adjacencyList[source].append(destination)\n            nodeInDegree[destination] += 1\n            totalEdges += 1\n        zeroInDegreeQueue = deque([node for node in range(numCourses) if node not in nodeInDegree])\n        edgesTraversed = 0\n        while zeroInDegreeQueue:\n            node = zeroInDegreeQueue.popleft()\n            for neighbour in adjacencyList[node]:\n                nodeInDegree[neighbour] -= 1\n                edgesTraversed += 1\n                if nodeInDegree[neighbour] == 0:\n                    zeroInDegreeQueue.append(neighbour)\n        return edgesTraversed == totalEdges","hash":"0448a24fe772a73dccb8ee18eda27ecf447e5fb5f2adba2378a2167fac3e57f4","origins":[{"source":"solutions","path":"LeetCoding Challenges/2023/2023-07 Leetcoding Challenge/13-JUL 207 Course Schedule.py"}]}],"sources":["solutions"]}});
